package com.turboio.addon;
import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;

/** Original journal API's daily AI summary only. No event transcripts, audio,
 * outline sources, coordinates or download credentials enter this projection. */
final class DailySummary {
 final String date,timezone,title,text;
 DailySummary(String date,String timezone,String title,String text){this.date=date;this.timezone=timezone;this.title=title;this.text=text;}
 static List<DailySummary> latest(byte[] bytes){Map<String,Object> root=WireJson.map(WireJson.read(OfficialLifelogJson.read(bytes).canonical));MaterialWire.require(Long.valueOf(0).equals(root.get("code")),"LIFELOG_RESPONSE_REJECTED");List<Object> rows=WireJson.list(root.get("data"));MaterialWire.require(rows.size()<=32,"DAILY_SUMMARY_BUDGET");Map<String,DailySummary> found=new TreeMap<>();for(Object raw:rows){Map<String,Object> row=WireJson.map(raw);if(!"daily".equals(row.get("periodType")))continue;String date=MaterialWire.text(row.get("periodStart"),10,false),end=MaterialWire.text(row.get("periodEnd"),10,false),zone=MaterialWire.text(row.get("timezone"),80,false);LocalDate day=LocalDate.parse(date);MaterialWire.require(end.equals(date),"DAILY_SUMMARY_RANGE_UNSUPPORTED");ZoneId.of(zone);Object context=row.get("context");if(!(context instanceof String)||((String)context).trim().isEmpty()||!(row.get("generatedAt") instanceof String)||((String)row.get("generatedAt")).isEmpty())continue;String text=MaterialWire.text(context,65536,false),title=MaterialWire.text(row.get("title"),512,true);DailySummary previous=found.put(date+"\n"+zone,new DailySummary(date,zone,title,text));MaterialWire.require(previous==null,"DAILY_SUMMARY_DUPLICATE");}return new ArrayList<>(found.values());}
 String id(String account){return "daily-"+TaskWire.hash((account+"\n"+date+"\n"+timezone).getBytes(StandardCharsets.UTF_8));}
 String markdown(){return "# "+date+" 每日 AI 总结\n\n"+(title.isEmpty()?"":title+"\n\n")+text;}
 Map<String,Object> body(String account,long revision){long start=LocalDate.parse(date).atStartOfDay(ZoneId.of(timezone)).toInstant().toEpochMilli(),end=LocalDate.parse(date).plusDays(1).atStartOfDay(ZoneId.of(timezone)).toInstant().toEpochMilli();Map<String,Object> body=WireJson.object("material_id",id(account),"revision",revision,"base_revision",revision-1,"operation","upsert","source","agent_analysis","started_at",TaskWire.now(start),"ended_at",TaskWire.now(end),"completeness","complete","text_revision",revision,"utterances",Collections.emptyList(),"speakers",Collections.emptyList(),"audio",WireJson.object("state","not_retained","sha256",null,"object_id",null),"full_text",WireJson.object("format","markdown","text",markdown(),"origin","legacy"),"processing",WireJson.object("transcription_state","unknown","covered_ms",null,"source_ms",null,"speaker","unavailable","boundary","unknown","recognition_channel","unknown","user_edited",false));MaterialWire.body(body);return body;}
}
